STORY={
'fr':dict(story='Notre histoire',title='D’une tente… à une aventure complète.',paragraphs=['Tout a commencé avec une idée simple : louer des tentes aux visiteurs qui souhaitaient passer une nuit dans la nature, à Imsfrane. À cette première expérience de camping se sont ajoutées, petit à petit, de nouvelles façons de découvrir notre région.','Les vélos sont arrivés, puis le rafting et un grand campement mobile. Aujourd’hui, nous préparons des séjours qui réunissent activités, nuits en plein air et repas pour les groupes. Nous installons le camp de zéro, montons les tentes et organisons la vie sur place.','Le projet a grandi, mais notre esprit reste le même : travailler ensemble, partager la nature de notre région et accueillir les visiteurs avec la chaleur de ses habitants.'],stages=['Les premières tentes','De nouvelles aventures','Un campement complet'],stageText=['La location de tentes, notre point de départ.','Le VTT et le rafting élargissent l’expérience.','Installation, hébergement et repas pour les groupes.'],team='Une équipe, une même énergie.',teamIntro='Cinq visages, une aventure collective. Nous partageons les préparatifs et le travail sur le terrain, de la montagne à la rivière et au campement.',experiences='Notre terrain de jeu',expTitle='La montagne, la rivière, le grand air.',expNames=['À pied, dans les montagnes','Au rythme de l’Ahansal','L’Atlas à deux roues','Vivre le campement'],expText=['Des sentiers aux panoramas de Msfrane, marcher ensemble et prendre le temps de découvrir.','Le rafting pour vivre la rivière avec notre équipe, lorsque la saison et le niveau de l’eau le permettent.','Des sorties VTT pour parcourir les pistes et découvrir les paysages autrement.','Un camp mobile monté pour votre séjour, avec les tentes et la préparation des repas pour les groupes.'],how='De la première idée au dernier souvenir.',howIntro='Une aventure se vit sur le terrain, mais elle se prépare bien avant le départ.',howNames=['On échange','On prépare','On vous accompagne'],howText=['Vos envies, le nombre de participants et les dates nous aident à dessiner le séjour.','Nous coordonnons le programme, le matériel, le campement et les repas selon la formule choisie.','Accueil, activités et vie au camp : nous restons présents au fil du séjour.'],companyTitle='Ichou Adventures, la même aventure qui grandit.',companyText='Fondée par Farid Laydi, la société Ichou Adventures prolonge cette histoire et accompagne le développement de nos expériences. Derrière le nom, vous retrouvez une équipe locale qui prépare les séjours et vous accueille sur le terrain.',link='Découvrir',caption='Le camping, là où notre histoire a commencé.',nav=['Notre histoire','L’équipe','Nos expériences']),
'en':dict(story='Our story',title='From one tent… to a complete adventure.',paragraphs=['It began with a simple idea: renting tents to visitors who wanted to spend a night outdoors in Imsfrane. Little by little, that first camping experience grew into new ways to discover our region.','Bicycles came next, followed by rafting and a large mobile camp. Today, we prepare stays combining outdoor activities, nights under canvas and meals for groups. We set up camp from scratch, pitch the tents and organise life on site.','The project has grown, but the spirit remains: working together, sharing the nature of our region and welcoming visitors with local hospitality.'],stages=['The first tents','New adventures','A complete camp'],stageText=['Tent rental was our starting point.','Mountain biking and rafting broaden the experience.','Camp setup, overnight stays and meals for groups.'],team='One team, a shared energy.',teamIntro='Five people, one collective adventure. We share the preparation and the work outdoors, in the mountains, on the river and at camp.',experiences='Where we explore',expTitle='Mountains, rivers and open air.',expNames=['Walking in the mountains','Following the Ahansal','The Atlas on two wheels','Life at camp'],expText=['From trails to Msfrane viewpoints, walk together and take time to explore.','Experience the river with our rafting team when the season and water levels allow.','Mountain bike outings to explore the tracks and see the landscape from another angle.','A mobile camp set up for your stay, with tents and meals prepared for groups.'],how='From the first idea to lasting memories.',howIntro='The adventure takes place outdoors, but the preparation starts well before departure.',howNames=['We talk','We prepare','We guide you'],howText=['Your wishes, group size and dates help us shape the stay.','We coordinate the itinerary, equipment, camp and meals according to your chosen package.','From welcoming you to the activities and life at camp, we stay involved throughout your visit.'],companyTitle='Ichou Adventures, a growing journey.',companyText='Founded by Farid Laydi, Ichou Adventures is the company continuing this story and supporting the development of our experiences. Behind the name is a local team preparing your stay and welcoming you outdoors.',link='Explore',caption='Camping, where our story began.',nav=['Our story','The team','Our experiences']),
'es':dict(story='Nuestra historia',title='De una tienda… a una aventura completa.',paragraphs=['Todo empezó con una idea sencilla: alquilar tiendas a quienes querían pasar una noche en la naturaleza de Imsfrane. Poco a poco, aquella primera experiencia de camping dio paso a nuevas formas de descubrir nuestra región.','Llegaron las bicicletas, después el rafting y un gran campamento móvil. Hoy preparamos estancias que combinan actividades, noches al aire libre y comidas para grupos. Montamos el campamento desde cero y organizamos la vida en el lugar.','El proyecto ha crecido, pero el espíritu sigue siendo el mismo: trabajar juntos, compartir nuestra naturaleza y recibir a los visitantes con la hospitalidad de la región.'],stages=['Las primeras tiendas','Nuevas aventuras','Un campamento completo'],stageText=['El alquiler de tiendas fue nuestro punto de partida.','La BTT y el rafting amplían la experiencia.','Montaje, alojamiento y comidas para grupos.'],team='Un equipo, una misma energía.',teamIntro='Cinco personas, una aventura colectiva. Compartimos la preparación y el trabajo en la montaña, en el río y en el campamento.',experiences='Nuestro entorno',expTitle='Montaña, río y aire libre.',expNames=['Caminar por la montaña','Al ritmo del Ahansal','El Atlas sobre dos ruedas','Vivir el campamento'],expText=['De los senderos a los miradores de Msfrane, caminar juntos y disfrutar del camino.','Rafting con nuestro equipo cuando la temporada y el nivel del agua lo permiten.','Rutas BTT por las pistas para descubrir el paisaje de otra manera.','Un campamento móvil preparado para vuestra estancia, con tiendas y comidas para grupos.'],how='De la primera idea al recuerdo del viaje.',howIntro='La aventura se vive al aire libre, pero se prepara mucho antes de salir.',howNames=['Hablamos','Preparamos','Os acompañamos'],howText=['Vuestras preferencias, el tamaño del grupo y las fechas nos ayudan a preparar la estancia.','Coordinamos el programa, el material, el campamento y las comidas según la fórmula elegida.','Desde la bienvenida hasta las actividades y la vida en el campamento, estamos presentes durante la estancia.'],companyTitle='Ichou Adventures, una aventura que crece.',companyText='Fundada por Farid Laydi, la empresa Ichou Adventures continúa esta historia y acompaña el desarrollo de nuestras experiencias. Detrás del nombre hay un equipo local que prepara las estancias y os recibe en el lugar.',link='Descubrir',caption='El camping, donde empezó nuestra historia.',nav=['Nuestra historia','El equipo','Experiencias']),
'ar':dict(story='قصتنا',title='من خيمة… لمغامرة كاملة.',paragraphs=['بدينا بفكرة بسيطة: كراء الخيام للناس اللي بغاو يعيشو تجربة المبيت وسط الطبيعة فمسفران. خطوة بخطوة، كبر المشروع وتوسّعات التجارب ديالنا، من التخييم لجولات الدراجات الجبلية والرافتينغ.','واليوم، ولّينا فريق كينظّم الرحلات والإقامات، وعندنا مخيم متنقل كبير كنجهّزوه من الصفر، بالخيام ومستلزمات المبيت، وحتى تحضير الوجبات للمجموعات.','كبرت الإمكانيات، وبقات الروح نفسها: نخدمو مجموعين ونشاركو مع الزوار طبيعة منطقتنا وحسن الضيافة ديال أهلها.'],stages=['البداية بالخيام','تجارب جديدة','مخيم متكامل'],stageText=['كراء الخيام كان أول خطوة فالمشروع.','الدراجات الجبلية والرافتينغ وسّعو التجربة.','تجهيز المخيم والمبيت والماكلة للمجموعات.'],team='فريق واحد، ونفس الروح.',teamIntro='خمسة وجوه، ومغامرة جماعية. كنتقاسمو التحضير والخدمة فالميدان، من الجبل للنهر وحتى المخيم.',experiences='فين كنعيشو المغامرة',expTitle='الجبل، النهر والهواء الطلق.',expNames=['على مسالك الجبال','مع مياه أحنصال','الأطلس على عجلتين','الحياة فالمخيم'],expText=['من المسالك لإطلالات مسفران، كنمشيو مجموعين وكنعطيو الوقت للاكتشاف.','تجربة الرافتينغ مع الفريق، ملي كيسمح الموسم ومستوى الماء.','جولات بالدراجة الجبلية لاكتشاف المسالك والمناظر بطريقة أخرى.','مخيم متنقل كنجهّزوه للإقامة، بالخيام وتحضير الماكلة للمجموعات.'],how='من أول فكرة حتى لآخر ذكرى.',howIntro='المغامرة كتتعاش فالميدان، ولكن التحضير ديالها كيبدا قبل الانطلاق.',howNames=['كنتواصلو','كنوجدو','كنرافقوكم'],howText=['الرغبات ديالكم وعدد المشاركين والتواريخ كيساعدونا نوجدو الإقامة المناسبة.','كننسّقو البرنامج والمعدات والمخيم والوجبات حسب الصيغة اللي تختارو.','من الاستقبال للأنشطة والحياة فالمخيم، كنبقاو حاضرين خلال الإقامة.'],companyTitle='شركة Ichou Adventures، مغامرة كتكبر.',companyText='أسّس فريد العيدي شركة Ichou Adventures باش يواصل هاد المسار ويطوّر التجارب اللي كنقدمو. ووراء الاسم، كاين فريق محلي كيوجد الإقامات وكيستقبل الزوار فالميدان.',link='اكتشف',caption='التخييم، من هنا بدات قصتنا.',nav=['قصتنا','الفريق','التجارب'])
}

