CSS += "\n.team-about .founder-hero{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:48px;align-items:center;margin-bottom:38px}.team-about .founder-hero .team-heading{max-width:none;margin:0}.team-about .founder-hero h1{font-size:clamp(42px,4.7vw,64px)}.team-about .founder-photo{position:relative;margin:0;border-radius:18px;overflow:hidden;background:#cbdcdf}.team-about .founder-photo img{display:block;width:100%;height:540px;object-fit:cover;object-position:36% 42%}.team-about .founder-photo figcaption{position:absolute;inset-inline:0;bottom:0;margin:0;padding:50px 25px 22px;background:linear-gradient(transparent,#092b26df);color:#fff}.team-about .founder-photo strong{display:block;font-size:21px;line-height:1.5}.team-about .founder-photo span{font-size:12px;color:#f0d796}.team-about .founder-hero .about-nav{gap:16px}@media(max-width:700px){.team-about .founder-hero{grid-template-columns:1fr;gap:25px;margin-bottom:28px}.team-about .founder-hero h1{font-size:40px}.team-about .founder-photo img{height:390px;object-position:36% 38%}.team-about .founder-photo strong{font-size:19px}}"

def build(root=Path('public')):
 target=root/'images'/'team';target.mkdir(parents=True,exist_ok=True)
 for slug,_,_ in PEOPLE:
  payload=Path('team-portraits',slug+'.webp.b64').read_text().strip()
  (target/(slug+'.webp')).write_bytes(base64.b64decode(payload,validate=True))
 (root/'about-team.css').write_text(CSS)
 for lang,c in COPY.items():
  path=root/lang/'about'/'index.html';source=path.read_text()
  cards=[]
  for n,(slug,latin,arabic) in enumerate(PEOPLE):
   name=arabic if lang=='ar' else latin;role=c['founder'] if n==0 else c['manager']
   cards.append(f'<article class="person-card"><div class="person-portrait"><img src="{BASE}images/team/{slug}.webp" alt="{html.escape(name)}" width="720" height="960" loading="lazy" decoding="async"></div><div class="person-info"><h3>{name}</h3><p>{role}</p></div></article>')
  contact={'fr':'Parlons de votre prochaine aventure','en':'Plan your next adventure with us','es':'Prepara tu próxima aventura','ar':'خلّينا نوجدو معاك المغامرة الجاية'}[lang]
  t=STORY[lang]
  nav='<nav class="about-nav" aria-label="'+c['see']+'">'+''.join(f'<a href="#{anchor}">{label}</a>' for anchor,label in zip(['our-story','people','our-experiences'],t['nav']))+'</nav>'
  story=f'''<section class="story-block" id="our-story" aria-labelledby="story-title"><div class="story-layout"><div class="story-copy"><span class="chapter">01 / {t['story']}</span><h2 id="story-title">{t['title']}</h2>{''.join('<p>'+x+'</p>' for x in t['paragraphs'])}</div><figure class="story-image"><img src="{BASE}images/camping-1-800.webp" alt="{t['caption']}" width="800" height="600" loading="lazy" decoding="async"><figcaption>{t['caption']}</figcaption></figure></div><div class="evolution">{''.join(f'<div><span class="step-number">{n+1:02}</span><h3>{name}</h3><p>{text}</p></div>' for n,(name,text) in enumerate(zip(t['stages'],t['stageText'])))}</div></section>'''
  expdata=[('randonnee','rando-IMG_7453.webp'),('rafting','raft2-800.webp'),('vtt','vtt-800.webp'),('camping','camping-1-800.webp')]
  experiences=f'''<section class="experience-block" id="our-experiences"><span class="chapter">03 / {t['experiences']}</span><h2>{t['expTitle']}</h2><div class="experience-grid">{''.join(f'<a class="exp-card" href="{BASE}{lang}/{slug}/"><img src="{BASE}images/{image}" alt="{name}" width="800" height="600" loading="lazy" decoding="async"><div class="exp-copy"><h3>{name}</h3><p>{text}</p><span class="exp-link">{t["link"]} ↗</span></div></a>' for (slug,image),name,text in zip(expdata,t['expNames'],t['expText']))}</div></section>'''
  preparation=f'''<section class="preparation"><h2>{t['how']}</h2><p>{t['howIntro']}</p><div class="prep-grid">{''.join(f'<div class="prep-step"><span class="step-number">{n+1:02}</span><h3>{name}</h3><p>{text}</p></div>' for n,(name,text) in enumerate(zip(t['howNames'],t['howText'])))}</div></section>'''
  company=f'''<section class="company-block"><span class="chapter">ICHOU ADVENTURES</span><h2>{t['companyTitle']}</h2><p>{t['companyText']}</p><div class="team-contact"><a href="{BASE}{lang}/contact/">{contact} ↗</a></div></section>'''
  section=f'''<section class="team-section" id="our-team" aria-labelledby="team-title"><div class="wrap"><div class="founder-hero"><header class="team-heading"><div class="tag">{c['kicker']}</div><h1 id="team-title">{c['title']}</h1><p>{c['intro']}</p>{nav}</header><figure class="founder-photo"><img src="{BASE}images/team/farid-laydi.webp" alt="{PEOPLE[0][2] if lang=='ar' else PEOPLE[0][1]}" width="720" height="960" fetchpriority="high" decoding="async"><figcaption><strong>{PEOPLE[0][2] if lang=='ar' else PEOPLE[0][1]}</strong><span>{c['founder']}</span></figcaption></figure></div>{story}<section id="people"><span class="chapter">02 / {c['see']}</span><h2>{t['team']}</h2><p class="people-intro">{t['teamIntro']}</p><div class="people-grid">{''.join(cards)}</div></section>{experiences}{preparation}{company}</div></section>'''
  # Replace the entire previous About body with the new team page.
  body='<main class="team-about" id="mainContent">'+section+'</main>'
  source,count=re.subn(r'<main\b.*?</main>',lambda m:body,source,count=1,flags=re.S)
  assert count==1,f'About main not found: {lang}'
  source=re.sub(r'<style\b[^>]*>.*?</style>',lambda m:'' if 'main.aboutx' in m[0] else m[0],source,flags=re.S)
  source=re.sub(r'<link[^>]*href="[^"]*about-team.css[^"]*"[^>]*>','',source)
  source=source.replace('</head>',f'<link rel="stylesheet" href="{BASE}about-team.css?v=founder-hero4"></head>',1)
  path.write_text(source)
 print('Built equal-sized cards for 5 team members × 4 languages.')

if __name__=='__main__':build()
